const input = $input.first().json.output;
let post_title, post_content, post_keywords, post_tags, category_id;

if (typeof input === 'object' && input !== null) {
  post_title = input.post_title || null;
  post_content = input.post_content || null;
  post_keywords = input.post_keywords || null;
  post_tags = input.post_tags || null;
  category_id = (typeof input.category_id === 'number') ? input.category_id : (input.category_id ? parseInt(input.category_id, 10) : null);
} else {
  const raw = input || '';
  function extractField(text, fieldName) {
    const re = new RegExp('"' + fieldName + '"\\s*:\\s*"((?:[^"\\\\]|\\\\[\\s\\S])*)"', 's');
    const match = text.match(re);
    if (match) return match[1].replace(/\\n/g,'\n').replace(/\\r/g,'\r').replace(/\\t/g,'\t').replace(/\\"/g,'"').replace(/\\\\/g,'\\');
    return null;
  }
  function extractNumberField(text, fieldName) {
    const re = new RegExp('"' + fieldName + '"\\s*:\\s*(\\d+)');
    const match = text.match(re);
    return match ? parseInt(match[1], 10) : null;
  }
  // Loosely match a field even if the opening quote before the key name is missing
  // (some model responses drop it when a prior field's string wasn't closed properly)
  function extractFieldLoose(text, fieldName) {
    const re = new RegExp('"?' + fieldName + '"\\s*:\\s*"((?:[^"\\\\]|\\\\[\\s\\S])*)"', 's');
    const match = text.match(re);
    if (match) return match[1].replace(/\\n/g,'\n').replace(/\\r/g,'\r').replace(/\\t/g,'\t').replace(/\\"/g,'"').replace(/\\\\/g,'\\');
    return null;
  }
  post_title = extractField(raw, 'post_title');
  post_content = extractField(raw, 'post_content');
  post_keywords = extractField(raw, 'post_keywords') || extractFieldLoose(raw, 'post_keywords');
  post_tags = extractField(raw, 'post_tags') || extractFieldLoose(raw, 'post_tags');
  category_id = extractNumberField(raw, 'category_id');
  if (!post_title || !post_content) {
    try {
      let cleaned = raw.trim().replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/i,'').trim();
      const s = cleaned.indexOf('{'), e = cleaned.lastIndexOf('}');
      if (s !== -1 && e !== -1) {
        const p = JSON.parse(cleaned.substring(s, e+1));
        post_title = post_title || p.post_title;
        post_content = post_content || p.post_content;
        post_keywords = post_keywords || p.post_keywords;
        post_tags = post_tags || p.post_tags;
        category_id = category_id || p.category_id;
      }
    } catch(e) {}
  }
  // Strip stray trailing field-name fragments that leaked into post_content
  // when the model failed to close the string before the next key (e.g. '...text.\n\npost_keywords')
  if (post_content) {
    post_content = post_content.replace(/\n*\s*(post_keywords|post_tags|category_id)\s*$/i, '').trim();
  }
}

// post_keywords and post_tags can substitute for each other; only title+content are hard requirements
if (!post_keywords && post_tags) post_keywords = post_tags;
if (!post_tags && post_keywords) post_tags = post_keywords;
