function slugify(text) {
  return text.toLowerCase().replace(/<[^>]+>/g,'').replace(/[^a-z0-9\s-]/g,'').trim().replace(/\s+/g,'-');
}

function buildDropdownTOC(lines) {
  const tocItems = [];
  for (const line of lines) {
    const t = line.trim();
    const m = t.match(/^(?:[-*]|\d+\.)\s*\[(.+?)\]\(#(.+?)\)/);
    if (m) tocItems.push({ label: m[1], anchor: m[2] });
  }
  if (tocItems.length === 0) return null;

  const liHtml = tocItems.map((item, i) =>
    `    <li style="padding:2px 0;"><a href="#${item.anchor}" style="color:#8B4513;text-decoration:none;font-weight:bold;font-size:15px;line-height:2;">${i + 1}.&nbsp;&nbsp;${item.label}</a></li>`
  ).join('\n');

  return (
    `<div class="ez-toc-container" style="border:1px solid #d4b896;border-radius:6px;background:#fdf8f2;padding:20px 24px;margin:24px 0;font-family:Georgia,serif;">` +
    `<div style="display:flex;align-items:center;justify-content:space-between;">` +
    `<strong style="font-size:17px;color:#2c1a0e;">Table of Contents</strong>` +
    `<button onclick="var l=this.closest('.ez-toc-container').querySelector('ul');l.style.display=l.style.display==='none'?'block':'none';" style="background:none;border:1px solid #c8a97e;border-radius:4px;padding:3px 10px;cursor:pointer;font-size:13px;color:#5a3e28;">&#9660;</button>` +
    `</div>` +
    `<ul style="list-style:none;padding:12px 0 0 0;margin:0;">\n${liHtml}\n  </ul>` +
    `</div>`
  );
}

function mdToHtml(md) {
  const allLines = md.split('\n');
  const tocHtml = buildDropdownTOC(allLines);
  const filteredLines = allLines.filter(line => !line.trim().match(/^(?:[-*]|\d+\.)\s*\[.+?\]\(#.+?\)/));

  let html = '';
  let inUl = false, inOl = false;
  function closeList() { if (inUl) { html += '</ul>\n'; inUl = false; } if (inOl) { html += '</ol>\n'; inOl = false; } }
  function inlineFormat(t) {
    return t
      .replace(/\*\*\*(.+?)\*\*\*/g,'<strong><em>$1</em></strong>')
      .replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')
      .replace(/\*(.+?)\*/g,'<em>$1</em>')
      .replace(/`(.+?)`/g,'<code>$1</code>')
      .replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2">$1</a>');
  }
  for (const line of filteredLines) {
    const t = line.trim();
    if (!t) { closeList(); continue; }
    if (/^#{6} /.test(t)) { closeList(); html += '<h6>'+inlineFormat(t.replace(/^#{6} /,''))+'</h6>\n'; continue; }
    if (/^#{5} /.test(t)) { closeList(); html += '<h5>'+inlineFormat(t.replace(/^#{5} /,''))+'</h5>\n'; continue; }
    if (/^#{4} /.test(t)) { closeList(); html += '<h4>'+inlineFormat(t.replace(/^#{4} /,''))+'</h4>\n'; continue; }
    if (/^#{3} /.test(t)) { closeList(); html += '<h3>'+inlineFormat(t.replace(/^#{3} /,''))+'</h3>\n'; continue; }
    if (/^#{2} /.test(t)) { closeList(); const hText = t.replace(/^#{2} /,''); html += '<h2 id="'+slugify(hText)+'">'+inlineFormat(hText)+'</h2>\n'; continue; }
    if (/^#{1} /.test(t)) { closeList(); html += '<h1>'+inlineFormat(t.replace(/^#{1} /,''))+'</h1>\n'; continue; }
    const olM = t.match(/^\d+\.\s+(.+)/); if (olM) { if (inUl) { html += '</ul>\n'; inUl = false; } if (!inOl) { html += '<ol>\n'; inOl = true; } html += '<li>'+inlineFormat(olM[1])+'</li>\n'; continue; }
    const ulM = t.match(/^[-*]\s+(.+)/); if (ulM) { if (inOl) { html += '</ol>\n'; inOl = false; } if (!inUl) { html += '<ul>\n'; inUl = true; } html += '<li>'+inlineFormat(ulM[1])+'</li>\n'; continue; }
    closeList();
    html += '<p>'+inlineFormat(t)+'</p>\n';
  }
  closeList();
  if (tocHtml) html = tocHtml + '\n' + html;
  return html;
}

const post_content_html = mdToHtml(post_content);
return [{ json: { post_title, post_content: post_content_html, post_keywords, post_tags, category_id } }];

