const categoryId = $('Parse Article JSON').item.json.category_id;
const featuredMediaId = $('Upload Image').item.json.id;

// Skip pattern for unwanted headings
const skipPattern = /^(conclusion|faq|frequently asked|common questions?|q\s*&\s*a|summary|final|wrap|closing)/i;

// Try H2 headings first
const headings = [];
const h2Parts = raw.split(/<h2[^>]*>/i);
for (let i = 1; i < h2Parts.length; i++) {
  const closeIdx = h2Parts[i].search(/<\/h2>/i);
  if (closeIdx !== -1) {
    const heading = h2Parts[i].substring(0, closeIdx).replace(/<[^>]+>/g, '').trim();
    if (heading && !skipPattern.test(heading)) headings.push(heading);
  }
}

// Fallback to H3 if no H2 found
if (headings.length === 0) {
  const h3Parts = raw.split(/<h3[^>]*>/i);
  for (let i = 1; i < h3Parts.length; i++) {
    const closeIdx = h3Parts[i].search(/<\/h3>/i);
    if (closeIdx !== -1) {
      const heading = h3Parts[i].substring(0, closeIdx).replace(/<[^>]+>/g, '').trim();
      if (heading && !skipPattern.test(heading)) headings.push(heading);
    }
  }
}

// Fallback: markdown ## or ### headings
if (headings.length === 0) {
  const mdH = [...raw.matchAll(/^#{2,3}\s+(.+)$/gm)]
    .map(m => m[1].trim())
    .filter(h => !skipPattern.test(h));
  headings.push(...mdH);
}

// Final fallback: topic-based — guarantees at least 3 items
while (headings.length < 3) {
  const fallbacks = ['essentials', 'tips', 'guide'];
  headings.push(topic.trim() + ' ' + fallbacks[headings.length % 3]);
}

// Select exactly 3 headings spread across the article
let selected = [];
if (headings.length >= 6) {
  selected = [headings[1], headings[3], headings[5]];
} else if (headings.length >= 4) {
  selected = [headings[1], headings[2], headings[3]];
} else {
