function tokenize(text) { return text.toLowerCase().replace(/<[^>]+>/g,' ').replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(w => w.length >= 4); }
function semanticScore(imageHeading, sectionText) { const imgTokens = new Set(tokenize(imageHeading)); const secTokens = tokenize(sectionText); if (imgTokens.size === 0) return 0; let hits = 0; for (const w of secTokens) { if (imgTokens.has(w)) hits++; } const ih = imageHeading.toLowerCase(); const sh = sectionText.toLowerCase().replace(/<[^>]+>/g,' '); const directBonus = sh.includes(ih) ? 50 : 0; return Math.min(100, hits*5+directBonus); }
function makeFigure(img) { const safeTitle = (postTitle||'').replace(/"/g,'&quot;'); return '\n<figure class="wp-block-image size-large aligncenter" style="text-align:center;margin:32px auto;"><img src="'+img.url+'" alt="'+safeTitle+'" class="wp-image-'+img.id+'" style="width:100%;height:auto;display:block;margin:0 auto;border-radius:8px;" loading="lazy" /></figure>\n'; }
