const withSep = humanizerContent.replace(/(<h[2-6][^>]*>[\s\S]*?<\/h[2-6]>)/gi, SEP+'$1');
const parts = withSep.split(SEP);
const sections = parts.map((part, idx) => { const hMatch = part.match(/<h[2-6][^>]*>([\s\S]*?)<\/h[2-6]>/i); const headingText = hMatch ? hMatch[1].replace(/<[^>]+>/g,'').toLowerCase().trim() : ''; const isSkipped = !hMatch || /^(conclusion|faq|frequently asked|common questions?|q\s*&\s*a|summary|final|wrap|closing)/i.test(headingText); return { idx, headingText, content: part, isSkipped }; });
const injectedSections = new Set(); const imageAssignments = [];
for (let i = 0; i < images.length; i++) {
  const ih = imageHeadings[i] || ''; let bestScore = -1; let bestSectionIdx = -1;
  for (const sec of sections) { if (sec.isSkipped) continue; if (injectedSections.has(sec.idx)) continue; const score = semanticScore(ih, sec.headingText+' '+sec.content); if (score > bestScore) { bestScore = score; bestSectionIdx = sec.idx; } }
  if (bestSectionIdx === -1) { for (const sec of sections) { if (sec.isSkipped) continue; if (injectedSections.has(sec.idx)) continue; bestSectionIdx = sec.idx; break; } }
  if (bestSectionIdx !== -1) { injectedSections.add(bestSectionIdx); imageAssignments.push({ imageIdx: i, sectionIdx: bestSectionIdx }); } else { imageAssignments.push({ imageIdx: i, sectionIdx: -1 }); }
}
