for (const { imageIdx, sectionIdx } of imageAssignments) { if (sectionIdx === -1) continue; const part = resultParts[sectionIdx]; const pCount = (part.match(/<\/p>/gi)||[]).length; if (pCount === 0) continue; resultParts[sectionIdx] = injectAfterNthP(part, images[imageIdx], Math.min(2,pCount)); }
const content = resultParts.join('');
