const tweetText = $('AI Agent').first().json.output?.trim() || '';
const articleUrl = $('Post Article').first().json.link || '';
const featuredImageUrl = $('Upload Image').first().json.source_url || '';

// Validate tweet text exists
if (!tweetText) {
  throw new Error('AI Agent produced no tweet text.');
}

// Strip any URL the agent may have accidentally included
let cleanedText = tweetText.replace(/https?:\/\/\S+/g, '').trim();

if (cleanedText.length < 10) {
  throw new Error('Tweet too short — likely empty or malformed.');
}

// X limit: 280 chars total.
// Each URL counts as 23 chars (t.co). Two URLs + 2 spaces = 48 chars reserved.
const MAX_TWEET_BODY = 280 - 48;

// Truncate gracefully if too long — cut at last space before limit, add ellipsis
if (cleanedText.length > MAX_TWEET_BODY) {
  const cutoff = cleanedText.lastIndexOf(' ', MAX_TWEET_BODY - 3);
  cleanedText = cleanedText.substring(0, cutoff > 0 ? cutoff : MAX_TWEET_BODY - 3) + '...';
}

// Build final tweet: text + article link + featured image URL
let finalTweet = cleanedText;
if (articleUrl) finalTweet += ` ${articleUrl}`;
if (featuredImageUrl) finalTweet += ` ${featuredImageUrl}`;

return [{ json: { tweet: finalTweet, charCount: finalTweet.length } }];
